API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the API Gateway container

Container_Boundary(api_gateway, "API Gateway") {
    Component(CustomRoutingAndTransformationPlugin, "Custom Routing and Transformation Plugin", "Lua/Go", "Handles custom routing, transformation, and security checks at line rate.")
    Component(ProxyEngine, "Proxy Engine", "Kong/Envoy", "Proxies requests from external and internal clients to backend microservices.")
}

Rel(CustomRoutingAndTransformationPlugin, ProxyEngine, "Enforces security and transforms requests")

@enduml

Core Clinical Services.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Core Clinical Services container

Container_Boundary(core_clinical_services, "Core Clinical Services") {
    Component(PatientAdmissionController, "Patient Admission Controller", "Spring Boot REST Controller", "Manages patient admission workflows and intake processing.")
    Component(EMRService, "EMR Service", "Spring Boot Service", "Handles Electronic Medical Records retrieval and updates.")
    Component(SchedulingManager, "Scheduling Manager", "Spring Boot Service", "Manages appointment scheduling and conflict prevention using Redis locking.")
}

Rel(PatientAdmissionController, EMRService, "Invokes EMR creation and updates", "Sync")
Rel(SchedulingManager, EMRService, "Coordinates appointment details with patient records", "Sync")

@enduml

Redis Enterprise cluster.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Redis Enterprise cluster", "Redis Enterprise cluster") {
    Component("Distributed Caching Engine", "Distributed Caching Engine", "Redis Enterprise", "Delivers low-latency distributed caching for core clinical and billing data.")
    Component("Session Management Engine", "Session Management Engine", "Redis Enterprise", "Manages user and system sessions securely across hybrid environments.")
    Component("Appointment Locking Mechanism", "Appointment Locking Mechanism", "Redis Enterprise with CRDTs", "Handles distributed appointment locking ensuring consistency and conflict-free replication.")
}

Rel("Distributed Caching Engine", "Session Management Engine", "Shares memory space and state data")
Rel("Appointment Locking Mechanism", "Distributed Caching Engine", "Utilizes caching infrastructure for lock states")

@enduml
